-- Phase 9 approved-row decision proof (09-16, D-03, APPR-12). Generated by
-- `pnpm exec drizzle-kit generate --name approval_decision_proof` on top of the journal (position
-- 0013, after 0012_research_report_records), then hand-edited as 0007 and 0012 were:
--   1. `ADD COLUMN` spelled out, and `IF NOT EXISTS` added to the trigger, because drizzle-kit does
--      not emit it and a partly set-up store must never fail a service start on this file.
--   2. The write-once trigger below, which drizzle-kit cannot express.
--
-- REBUILD HAZARD (see 0007): this file adds a column with ALTER TABLE ... ADD COLUMN and never
-- rebuilds `proposals`. A table rebuild (copy to a new table, DROP, RENAME) would drop every
-- Phase 6 trigger on the table. `migration-decision-proof.audit.test.ts` pins that this file contains
-- no such rebuild, and the approval store's survival test pins the trigger names.
--
-- `decision_proof` holds the service's proof that a row was approved through the service: strict JSON
-- `{ "v": 1, "mac": <64 hex>, "presence": null }`. NULL for every pending, denied, expired or
-- withdrawn row and for every row approved before this migration (those fail verification, closed).
-- The proof is DETECTION, not a boundary: a same-user process that can read the install secret can
-- compute a valid MAC (R-02).
--
-- Applied files are never renumbered, renamed or edited (ADR-0018, M-1).
ALTER TABLE `proposals` ADD COLUMN `decision_proof` text;
--> statement-breakpoint
-- The proof is written exactly once, by the update that moves a pending row to approved, and never
-- changes afterwards. It cannot be set on a pending row without that move, set on a row that is
-- denied, expired or withdrawn, filled in later on a row approved with none, or rewritten or cleared on
-- an approved row. `UPDATE OF` fires when the column is named in the SET list; the WHEN clause lets a
-- no-op assignment (the new value equals the old one) through.
CREATE TRIGGER IF NOT EXISTS `proposals_decision_proof_write_once` BEFORE UPDATE OF `decision_proof` ON `proposals`
WHEN NEW.`decision_proof` IS NOT OLD.`decision_proof`
	AND NOT (OLD.`decision_proof` IS NULL AND OLD.`state` = 'pending' AND NEW.`state` = 'approved')
BEGIN
	SELECT RAISE(ABORT, 'decision_proof is written once, at approval');
END;
